using System.Data;using Microsoft.Data.SqlClient;using TransPort.Api.Configuration;using TransPort.Api.Modules.Maquinaria.DTOs;using TransPort.Api.Modules.Shared.DTOs;using TransPort.Api.Modules.Shared.Repositories;
namespace TransPort.Api.Modules.Maquinaria.Repositories;
public sealed class MaquinariaRepository(ISqlConnectionFactory connections):IMaquinariaRepository
{
 public async Task<IReadOnlyList<MaquinariaEquipoDto>>ListarAsync(string?estado,int?sedeId,string?busqueda,AlcanceMaquinaria a,CancellationToken ct){var x=new List<MaquinariaEquipoDto>();await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_leer_listado");Scope(c,a);c.Parameters.Add("@Estado",SqlDbType.NVarChar,30).Value=Db(T(estado));c.Parameters.Add("@SedeId",SqlDbType.Int).Value=Db(sedeId);c.Parameters.Add("@Busqueda",SqlDbType.NVarChar,120).Value=Db(T(busqueda));await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(Equipo(r));return x;}
 public async Task<MaquinariaDetalleDto?>ObtenerAsync(int id,AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_leer_por_id");c.Parameters.Add("@Id",SqlDbType.Int).Value=id;Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var e=new MaquinariaDetalleDto(r.Int32("MaquinariaEquipoId"),r.Int32("SedeId"),r.Text("Sede"),r.Text("Codigo"),r.Text("Tipo"),r.Text("Marca"),r.Text("Modelo"),NS(r,"Anio"),r.Text("Estado"),ND(r,"PrecioVenta"),ND(r,"TarifaDiaria"),D(r,"HorasUso"),r.NullableText("Observacion"),r.Date("FechaCreacion"),r.NullableDate("FechaModificacion"),[],[]);var cs=new List<MaquinariaContratoDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))cs.Add(new(r.Int64("MaquinariaContratoId"),r.Int32("ClienteId"),r.Text("Cliente"),r.Text("Tipo"),r.Date("FechaInicio"),r.NullableDate("FechaFin"),D(r,"MontoTotal"),D(r,"Deposito"),r.Text("Estado"),ND(r,"HorasEntrega"),ND(r,"HorasDevolucion"),r.Text("Responsable"),r.NullableText("Observacion"),r.Date("FechaCreacion")));var ms=new List<MaquinariaMantenimientoDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))ms.Add(new(r.Int64("MaquinariaMantenimientoId"),r.Text("Tipo"),r.Date("FechaProgramada"),r.NullableDate("FechaCompletada"),D(r,"Costo"),r.Text("Estado"),r.Text("Responsable"),r.NullableText("Observacion"),r.Date("FechaCreacion")));return e with{Contratos=cs,Mantenimientos=ms};}
 public async Task<MaquinariaOpcionesDto>OpcionesAsync(AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_leer_opciones");Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);var s=await Cats(r,ct);var cl=await r.NextResultAsync(ct)?await Cats(r,ct):[];return new(s,cl);}
 public async Task<int>CrearEquipoAsync(CrearMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_crear_equipo");c.Parameters.Add("@SedeId",SqlDbType.Int).Value=x.SedeId;c.Parameters.Add("@Codigo",SqlDbType.NVarChar,50).Value=x.Codigo.Trim();c.Parameters.Add("@Tipo",SqlDbType.NVarChar,80).Value=x.Tipo.Trim();c.Parameters.Add("@Marca",SqlDbType.NVarChar,80).Value=x.Marca.Trim();c.Parameters.Add("@Modelo",SqlDbType.NVarChar,80).Value=x.Modelo.Trim();c.Parameters.Add("@Anio",SqlDbType.SmallInt).Value=Db(x.Anio);NDec(c,"@PrecioVenta",x.PrecioVenta);NDec(c,"@TarifaDiaria",x.TarifaDiaria);Dec(c,"@HorasUso",x.HorasUso);c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(x.Observacion));Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct));}
 public async Task<long>CrearContratoAsync(CrearContratoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_crear_contrato");c.Parameters.Add("@EquipoId",SqlDbType.Int).Value=x.EquipoId;c.Parameters.Add("@ClienteId",SqlDbType.Int).Value=x.ClienteId;c.Parameters.Add("@Tipo",SqlDbType.NVarChar,20).Value=x.Tipo.Trim();c.Parameters.Add("@FechaInicio",SqlDbType.Date).Value=x.FechaInicio.Date;c.Parameters.Add("@FechaFin",SqlDbType.Date).Value=Db(x.FechaFin?.Date);Dec(c,"@MontoTotal",x.MontoTotal);Dec(c,"@Deposito",x.Deposito);c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(x.Observacion));Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}
 public Task<bool>EstadoContratoAsync(long id,EstadoContratoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct)=>State("sp_maquinaria_actualizar_contrato",id,x.Estado,x.Observacion,x.HorasDevolucion,a,ct);
 public async Task<long>CrearMantenimientoAsync(CrearMantenimientoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_crear_mantenimiento");c.Parameters.Add("@EquipoId",SqlDbType.Int).Value=x.EquipoId;c.Parameters.Add("@Tipo",SqlDbType.NVarChar,80).Value=x.Tipo.Trim();c.Parameters.Add("@FechaProgramada",SqlDbType.Date).Value=x.FechaProgramada.Date;Dec(c,"@Costo",x.Costo);c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(x.Observacion));Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}
 public async Task<bool>EstadoMantenimientoAsync(long id,EstadoMantenimientoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_actualizar_mantenimiento");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@Estado",SqlDbType.NVarChar,20).Value=x.Estado.Trim();c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(x.Observacion));Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 public async Task<bool>EliminarEquipoAsync(int id,int u,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_maquinaria_eliminar_equipo");c.Parameters.Add("@Id",SqlDbType.Int).Value=id;c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=u;return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 private async Task<bool>State(string p,long id,string estado,string?obs,decimal?horas,AlcanceMaquinaria a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,p);c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;c.Parameters.Add("@Estado",SqlDbType.NVarChar,20).Value=estado.Trim();NDec(c,"@HorasDevolucion",horas);c.Parameters.Add("@Observacion",SqlDbType.NVarChar,500).Value=Db(T(obs));Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 private static MaquinariaEquipoDto Equipo(SqlDataReader r)=>new(r.Int32("MaquinariaEquipoId"),r.Int32("SedeId"),r.Text("Sede"),r.Text("Codigo"),r.Text("Tipo"),r.Text("Marca"),r.Text("Modelo"),NS(r,"Anio"),r.Text("Estado"),ND(r,"PrecioVenta"),ND(r,"TarifaDiaria"),D(r,"HorasUso"),r.NullableText("Observacion"),r.Date("FechaCreacion"));private static async Task<IReadOnlyList<CatalogoDto>>Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}private static void Scope(SqlCommand c,AlcanceMaquinaria a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static SqlCommand P(SqlConnection c,string n)=>new(n,c){CommandType=CommandType.StoredProcedure};private static object Db(object?x)=>x??DBNull.Value;private static string?T(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static decimal D(SqlDataReader r,string n)=>r.GetDecimal(r.GetOrdinal(n));private static decimal?ND(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetDecimal(i);}private static short?NS(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt16(i);}private static void Dec(SqlCommand c,string n,decimal v){var p=c.Parameters.Add(n,SqlDbType.Decimal);p.Precision=18;p.Scale=2;p.Value=v;}private static void NDec(SqlCommand c,string n,decimal?v){var p=c.Parameters.Add(n,SqlDbType.Decimal);p.Precision=18;p.Scale=2;p.Value=Db(v);}
}
